// Extraction sans LLM : motif sur la reference de facture, adresse de
// l'expediteur, corps du message tel quel, en-tetes du mail s'il y en a.
//
// L'expediteur vient d'un champ de la source, jamais du texte du message :
// une adresse citee dans un message n'est pas celle de qui l'a ecrit
// (ADR-011). Sans expediteur, l'API refuse la requete et la branche
// d'erreur previent une personne.
//
// Une reference de facture introuvable n'est pas une erreur : le run part
// sur insufficient_information, deja gere par l'API.

const body = $input.first().json.body ?? $input.first().json;
const text = String(body.message ?? body.text ?? '');

const invoice = text.match(/\binv[_-]?([A-Za-z0-9]{3,})\b/i);
const email = body.customer_email ?? body.from ?? null;
const headers =
  body.headers && typeof body.headers === 'object' ? body.headers : null;

return [{
  json: {
    message: text,
    customer_email: email,
    invoice_id: invoice ? invoice[0].replace('-', '_') : null,
    headers,
    extraction_ok: Boolean(email)
  }
}];

